// ============================================================
// Independent closed-form Ascendant formula -- a genuinely SEPARATE
// computational path from packages/lagna/src/ascendant.ts's own
// rotation-based root-finder, used ONLY here in the test file to
// cross-validate the production engine, never imported by production
// code.
// ============================================================

function independentMeanObliquityDegrees(date: Date): number {
  const t = (Astronomy.MakeTime(date).tt) / 36525; // Julian centuries of Terrestrial Time since J2000
  const arcsec = 23 * 3600 + 26 * 60 + 21.448 - 46.815 * t - 0.00059 * t * t + 0.001813 * t * t * t; // Meeus (22.2), mean obliquity
  return arcsec / 3600;
}

function independentRamcDegrees(date: Date, eastLongitude: number): number {
  const gstDegrees = Astronomy.SiderealTime(date) * 15; // Greenwich Apparent Sidereal Time, hours -> degrees
  return ((gstDegrees + eastLongitude) % 360 + 360) % 360;
}

function independentClosedFormAscendant(ramcDegrees: number, obliquityDegrees: number, latitudeDegrees: number): number {
  const ramc = (ramcDegrees * Math.PI) / 180;
  const eps = (obliquityDegrees * Math.PI) / 180;
  const lat = (latitudeDegrees * Math.PI) / 180;
  const y = Math.cos(ramc);
  const x = -(Math.sin(eps) * Math.tan(lat) + Math.cos(eps) * Math.sin(ramc));
  let ascendant = (Math.atan2(y, x) * 180) / Math.PI;
  if (ascendant < 0) ascendant += 360;
  return ascendant;
}

