// --- Fixture 1: Enschede, Netherlands (REAL external source) ---
// Source: RadixPro "The ascendant" (https://radixpro.com/a4a-start/the-ascendant/),
// a technical astrology-software reference documenting worked house-system
// calculations -- retrieved via web search (the page itself returns HTTP 403
// to direct fetches). The source states, for Enschede (52 deg 13' N, 6 deg 54' E),
// 2 November 2016, 21:17:30 UT:
//   sidereal time = 0:35:23.6 (decimal 0.5899018653 hours)
//   obliquity E   = 23 deg 26' 13.56586091" (decimal 23.437101628 degrees)
//   RAMC = 15 * 0.5899018653 = 8.8485279795 degrees
// These are the SOURCE's own stated intermediates, not this package's.
// Applying the independent closed-form formula (this file's own
// independentClosedFormAscendant, NOT production code) to those exact
// externally-published numbers:
const EXT_ENSCHEDE_RAMC = 8.8485279795;
const EXT_ENSCHEDE_OBLIQUITY = 23.437101628;
const EXT_ENSCHEDE_LATITUDE = 52 + 13 / 60; // 52.2166666666667
const EXPECTED_ENSCHEDE_ASCENDANT_FROM_EXTERNAL_SOURCE = independentClosedFormAscendant(EXT_ENSCHEDE_RAMC, EXT_ENSCHEDE_OBLIQUITY, EXT_ENSCHEDE_LATITUDE);
// = 123.50798... degrees (Karka/Cancer)

const ENSCHEDE_BIRTH = new Date('2016-11-02T21:17:30.000Z');
const ENSCHEDE_LON = 6 + 54 / 60; // 6.9

check(
  'Fixture 1 (Enschede, external RadixPro source): this package\'s own astronomy-engine-derived obliquity matches the externally-published obliquity to within 1e-4 degrees (confirms this package\'s ephemeris/time handling is consistent with the external source)',
  Math.abs(independentMeanObliquityDegrees(ENSCHEDE_BIRTH) - EXT_ENSCHEDE_OBLIQUITY) < 1e-4
);

check(
  'Fixture 1 (Enschede): this package\'s own astronomy-engine-derived RAMC matches the externally-published RAMC to within 0.01 degrees (36 arcsec -- small residual expected from apparent-vs-mean sidereal time / nutation model differences between libraries)',
  Math.abs(independentRamcDegrees(ENSCHEDE_BIRTH, ENSCHEDE_LON) - EXT_ENSCHEDE_RAMC) < 0.01
);

check(
  'Fixture 1 (Enschede): production calculateNatalAscendant\'s tropical longitude matches the externally-sourced closed-form Ascendant to within 0.01 degrees',
  Math.abs(calculateNatalAscendant(ENSCHEDE_BIRTH, EXT_ENSCHEDE_LATITUDE, ENSCHEDE_LON).tropicalLongitude - EXPECTED_ENSCHEDE_ASCENDANT_FROM_EXTERNAL_SOURCE) < 0.01
);

check(
  'Fixture 1 (Enschede): production tropical Ascendant also matches the closed-form formula applied to THIS package\'s own library-derived RAMC/obliquity, to within 0.005 degrees (cross-checks the rotation-based algorithm against a fully independent formula, not merely against the external source)',
  (() => {
    const ramc = independentRamcDegrees(ENSCHEDE_BIRTH, ENSCHEDE_LON);
    const eps = independentMeanObliquityDegrees(ENSCHEDE_BIRTH);
    const expected = independentClosedFormAscendant(ramc, eps, EXT_ENSCHEDE_LATITUDE);
    const actual = calculateNatalAscendant(ENSCHEDE_BIRTH, EXT_ENSCHEDE_LATITUDE, ENSCHEDE_LON).tropicalLongitude;
    return Math.abs(actual - expected) < 0.005;
  })()
);

